/** Legacy fixtures for tests of `src/io/legacy-v6` (step 3.8): the frozen Phase 0 files and the oracles generated by the same method. Test-only. */
import { readFileSync } from 'node:fs';

/** A file of `data/fixtures/legacy/` (frozen Phase 0 fixtures and the oracles next to them). */
export function legacyFixture(name: string): unknown {
  return JSON.parse(readFileSync(new URL(`../../data/fixtures/legacy/${name}`, import.meta.url), 'utf8')) as unknown;
}

/** A file of `tests/fixtures/legacy-v6/`: inputs and oracles generated by `scripts/legacy-oracle.mjs` (step 3.8). */
export function legacyTestFixture(name: string): unknown {
  return JSON.parse(readFileSync(new URL(`../../tests/fixtures/legacy-v6/${name}`, import.meta.url), 'utf8')) as unknown;
}

/** `JSON.parse(JSON.stringify(value))`: what the oracle file would hold for a value (drops `undefined`, like JSON does). */
export const viaJson = <T>(value: T): unknown => JSON.parse(JSON.stringify(value)) as unknown;
